SELECT SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 11 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'public' AND analytics_order_facts.payment_method = 'wallet' LIMIT 1000
